+import {
+    AttachRolePolicyCommand,
+    CreatePolicyCommand,
+    CreateRoleCommand,
+    IAMClient,
+    UpdateAssumeRolePolicyCommand,
+} from '@aws-sdk/client-iam';
+import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
+import { Injectable, InternalServerErrorException } from '@nestjs/common';
+import { v4 } from 'uuid';
+import { DatastoreAccessInformation, SupportedDatastores } from './entities/measurement-config.entity';
+
+@Injectable()
+export class DatastoreAccessService {
+    private readonly iam = new IAMClient({ region: process.env.AWS_REGION || 'us-east-1' });
+    private readonly s3 = new S3Client({ region: process.env.AWS_REGION || 'us-east-1' });
+
+    async provision(
+        configuration: DatastoreAccessInformation,
+        businessID: string,
+        measurementId: string
+    ): Promise<DatastoreAccessInformation> {
+        const configured = this.withGeneratedLocations(configuration, businessID);
+        const externalId = v4();
+        const uniqueSuffix = measurementId.replace(/[^a-zA-Z0-9]/g, '').slice(0, 16);
+        const businessName = businessID.replace(/[^a-zA-Z0-9+=,.@_-]/g, '-').slice(0, 28);
+        const roleName = `paigo-s3-${businessName}-${uniqueSuffix}`;
+        const policyName = `${roleName}-access`;
+
+        const role = await this.iam.send(
+            new CreateRoleCommand({
+                RoleName: roleName,
+                AssumeRolePolicyDocument: this.trustPolicy(configured.accountId, externalId),
+                Description: `S3 usage ingestion for Paigo business ${businessID}`,
+            })
+        );
+        if (!role.Role?.Arn) {
+            throw new InternalServerErrorException('AWS did not return an ARN for the datastore ingestion role');
+        }
+
+        const policy = await this.iam.send(
+            new CreatePolicyCommand({
+                PolicyName: policyName,
+                Description: `S3 usage ingestion access for Paigo business ${businessID}`,
+                PolicyDocument: this.accessPolicy(businessID),
+            })
+        );
+        if (!policy.Policy?.Arn) {
+            throw new InternalServerErrorException('AWS did not return an ARN for the datastore ingestion policy');
+        }
+
+        await this.iam.send(new AttachRolePolicyCommand({ RoleName: roleName, PolicyArn: policy.Policy.Arn }));
+        return new DatastoreAccessInformation({ ...configured, iamRoleArn: role.Role.Arn, externalId });
+    }
+
+    async updateAccount(
+        current: DatastoreAccessInformation,
+        update: Partial<DatastoreAccessInformation>,
+        businessID: string
+    ): Promise<DatastoreAccessInformation> {
+        const configured = this.withGeneratedLocations({ ...current, ...update }, businessID);
+        if (update.accountId && update.accountId !== current.accountId) {
+            const roleName = current.iamRoleArn.split('/').pop();
+            if (!roleName || !current.externalId) {
+                throw new InternalServerErrorException('Stored datastore configuration is missing IAM role details');
+            }
+            await this.iam.send(
+                new UpdateAssumeRolePolicyCommand({
+                    RoleName: roleName,
+                    PolicyDocument: this.trustPolicy(update.accountId, current.externalId),
+                })
+            );
+        }
+        return new DatastoreAccessInformation({
+            ...configured,
+            iamRoleArn: current.iamRoleArn,
+            externalId: current.externalId,
+        });
+    }
+
+    async writeToDlq(businessID: string, sourceKey: string, failedInput: unknown, error: unknown): Promise<void> {
+        const key = `${this.relativeSourceKey(sourceKey)}.message.text`;
+        await this.s3.send(
+            new PutObjectCommand({
+                Bucket: this.dlqBucket,
+                Key: key,
+                ContentType: 'application/json',
+                Body: JSON.stringify({
+                    failedInput,
+                    processingMetadata: {
+                        businessID,
+                        sourceKey,
+                        failedAt: new Date().toISOString(),
+                        error: error instanceof Error ? error.message : String(error),
+                    },
+                }),
+            })
+        );
+    }
+
+    relativeSourceKey(sourceKey: string): string {
+        if (!sourceKey) return 'unknown';
+        if (!sourceKey.startsWith('s3://')) return sourceKey.replace(/^\/+/, '');
+        const withoutScheme = sourceKey.slice('s3://'.length);
+        const firstSlash = withoutScheme.indexOf('/');
+        return firstSlash === -1 ? withoutScheme : withoutScheme.slice(firstSlash + 1);
+    }
+
+    private withGeneratedLocations(
+        configuration: Partial<DatastoreAccessInformation>,
+        businessID: string
+    ): DatastoreAccessInformation {
+        const region = configuration.region || 'us-east-1';
+        return new DatastoreAccessInformation({
+            ...configuration,
+            platform: configuration.platform || SupportedDatastores.s3,
+            region,
+            ingestion: `s3://${this.ingestionBucket}/${businessID}/`,
+            dlq: `s3://${this.dlqBucket}/${businessID}/`,
+        } as DatastoreAccessInformation);
+    }
+
+    private trustPolicy(accountId: string, externalId: string): string {
+        return JSON.stringify({
+            Version: '2012-10-17',
+            Statement: [
+                {
+                    Effect: 'Allow',
+                    Principal: { AWS: `arn:aws:iam::${accountId}:root` },
+                    Action: 'sts:AssumeRole',
+                    Condition: { StringEquals: { 'sts:ExternalId': externalId } },
+                },
+            ],
+        });
+    }
+
+    private accessPolicy(businessID: string): string {
+        return JSON.stringify({
+            Version: '2012-10-17',
+            Statement: [
+                {
+                    Effect: 'Allow',
+                    Action: ['s3:PutObject'],
+                    Resource: [`arn:aws:s3:::${this.ingestionBucket}/${businessID}/*`],
+                },
+                {
+                    Effect: 'Allow',
+                    Action: ['s3:GetObject'],
+                    Resource: [`arn:aws:s3:::${this.dlqBucket}/${businessID}/*`],
+                },
+            ],
+        });
+    }
+
+    private get ingestionBucket(): string {
+        return process.env.DB_MEASUREMENT_BUCKET_NAME || 'paigo-usage-record-dump-bucket';
+    }
+
+    private get dlqBucket(): string {
+        return process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME || 'paigo-usage-record-dlq-bucket';
+    }
+}
